import { createClient } from "npm:@supabase/supabase-js@2";
import { resolveSmoobuProperty } from "./propertyMapping.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
);

interface SmoobuPayload {
  external_id?: string;
  property_name?: string;
  client_name?: string;
  check_in?: string;
  check_out?: string;
  status?: string;
  guest_name?: string | null;
  synced_at?: string | null;
  dry_run?: boolean;
}

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function isValidIsoDate(value: string | undefined): boolean {
  return Boolean(value && /^\d{4}-\d{2}-\d{2}$/.test(value));
}

function normalizedStatus(value: string | undefined): "confirmed" | "modified" | "cancelled" | "canceled" | "no_show" {
  const status = (value ?? "confirmed").trim().toLowerCase().replace(/\s+/g, "_");
  if (["confirmed", "modified", "cancelled", "canceled", "no_show"].includes(status)) {
    return status as "confirmed" | "modified" | "cancelled" | "canceled" | "no_show";
  }
  throw new Error(`Estado Smoobu no permitido: ${value}`);
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

  const expectedKey = Deno.env.get("SMOOBU_SYNC_API_KEY");
  const authHeader = req.headers.get("Authorization") ?? "";
  if (!expectedKey || authHeader !== `Bearer ${expectedKey}`) {
    return json({ error: "Unauthorized" }, 401);
  }

  let payload: SmoobuPayload;
  try {
    payload = await req.json();
  } catch {
    return json({ error: "Invalid JSON body" }, 400);
  }

  const externalId = payload.external_id?.trim();
  const propertyName = payload.property_name?.trim();
  const clientName = payload.client_name?.trim();
  const checkIn = payload.check_in?.trim();
  const checkOut = payload.check_out?.trim();

  if (!externalId || !propertyName || !clientName || !checkIn || !checkOut) {
    return json({ error: "Faltan external_id, property_name, client_name, check_in o check_out" }, 400);
  }
  if (!isValidIsoDate(checkIn) || !isValidIsoDate(checkOut) || checkOut <= checkIn) {
    return json({ error: "El rango de fechas Smoobu no es válido" }, 400);
  }

  let status: ReturnType<typeof normalizedStatus>;
  try {
    status = normalizedStatus(payload.status);
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "Estado inválido" }, 400);
  }

  const { data: clients, error: clientError } = await supabase
    .from("clients")
    .select("id, nombre")
    .eq("nombre", clientName)
    .limit(2);
  if (clientError) return json({ error: "No se pudo resolver el cliente", detail: clientError.message }, 500);
  if (!clients || clients.length !== 1) {
    return json({ error: "Cliente inexistente o ambiguo", client_name: clientName }, 422);
  }

  const client = clients[0];
  const propertyResolution = await resolveSmoobuProperty(supabase, propertyName, client.id);
  if (!propertyResolution.ok) {
    return json({
      error: propertyResolution.error,
      code: propertyResolution.code,
      property_name: propertyName,
      detail: propertyResolution.detail,
    }, propertyResolution.status);
  }

  const property = propertyResolution.property;
  const resolution = {
    client_id: client.id,
    property_id: property.id,
    property_name: property.nombre,
    smoobu_property_name: propertyResolution.smoobuPropertyName,
    status,
    dry_run: Boolean(payload.dry_run),
  };

  if (payload.dry_run) return json({ status: "validated", resolution });

  if (Deno.env.get("SMOOBU_WRITES_ENABLED") !== "true") {
    return json({ error: "Smoobu writes are disabled", resolution }, 409);
  }

  const { data: result, error: applyError } = await supabase.rpc("apply_smoobu_reservation", {
    _external_id: externalId,
    _property_name: property.nombre,
    _property_id: property.id,
    _cliente_id: client.id,
    _check_in: checkIn,
    _check_out: checkOut,
    _status: status,
    _guest_name: payload.guest_name ?? null,
    _synced_at: payload.synced_at ?? new Date().toISOString(),
  });

  if (applyError) {
    return json({ error: "No se pudo aplicar la reserva Smoobu", detail: applyError.message, resolution }, 500);
  }

  return json({ status: "applied", resolution, result });
});

export interface SmoobuMappedProperty {
  id: string;
  nombre: string;
  direccion: string | null;
  cliente_id: string;
  sede_id: string | null;
  duracion_servicio: number | null;
  coste_servicio: number | null;
  check_in_predeterminado: string | null;
  check_out_predeterminado: string | null;
}

export type SmoobuPropertyResolution =
  | { ok: true; property: SmoobuMappedProperty; smoobuPropertyName: string }
  | {
      ok: false;
      status: 422 | 500;
      code:
        | "property_mapping_missing"
        | "property_mapping_ambiguous"
        | "property_mapping_inactive"
        | "property_mapping_lookup_failed"
        | "property_missing"
        | "property_ambiguous"
        | "property_lookup_failed";
      error: string;
      detail?: string;
    };

type QueryClient = {
  from: (table: string) => {
    select: (columns: string) => any;
    eq: (column: string, value: string | boolean) => any;
    limit: (value: number) => Promise<{
      data: unknown[] | null;
      error: { message: string } | null;
    }>;
  };
};

export async function resolveSmoobuProperty(
  supabase: QueryClient,
  smoobuPropertyName: string,
  clientId: string,
): Promise<SmoobuPropertyResolution> {
  const normalizedName = smoobuPropertyName.trim();
  const { data: mappings, error: mappingError } = await supabase
    .from("smoobu_property_mappings")
    .select("smoobu_property_name, property_id, is_active")
    .eq("smoobu_property_name", normalizedName)
    .limit(2);

  if (mappingError) {
    return {
      ok: false,
      status: 500,
      code: "property_mapping_lookup_failed",
      error: "No se pudo consultar el mapeo de propiedad Smoobu",
      detail: mappingError.message,
    };
  }

  if (!mappings || mappings.length === 0) {
    return {
      ok: false,
      status: 422,
      code: "property_mapping_missing",
      error: "No existe un mapeo activo para la propiedad Smoobu",
    };
  }

  if (mappings.length !== 1) {
    return {
      ok: false,
      status: 422,
      code: "property_mapping_ambiguous",
      error: "La propiedad Smoobu tiene más de un mapeo",
    };
  }

  const mapping = mappings[0] as {
    smoobu_property_name: string;
    property_id: string;
    is_active: boolean;
  };

  if (!mapping.is_active) {
    return {
      ok: false,
      status: 422,
      code: "property_mapping_inactive",
      error: "El mapeo de la propiedad Smoobu está pausado",
    };
  }

  const { data: properties, error: propertyError } = await supabase
    .from("properties")
    .select("id, nombre, direccion, cliente_id, sede_id, duracion_servicio, coste_servicio, check_in_predeterminado, check_out_predeterminado")
    .eq("id", mapping.property_id)
    .eq("cliente_id", clientId)
    .limit(2);

  if (propertyError) {
    return {
      ok: false,
      status: 500,
      code: "property_lookup_failed",
      error: "No se pudo consultar la propiedad Limpatex asociada",
      detail: propertyError.message,
    };
  }

  if (!properties || properties.length === 0) {
    return {
      ok: false,
      status: 422,
      code: "property_missing",
      error: "La propiedad del mapeo no existe o no pertenece al cliente",
    };
  }

  if (properties.length !== 1) {
    return {
      ok: false,
      status: 422,
      code: "property_ambiguous",
      error: "La propiedad del mapeo es ambigua para el cliente",
    };
  }

  return {
    ok: true,
    property: properties[0] as SmoobuMappedProperty,
    smoobuPropertyName: mapping.smoobu_property_name,
  };
}
